CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'student', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS books (id SERIAL PRIMARY KEY, title VARCHAR(255) NOT NULL, author VARCHAR(255) NOT NULL, isbn VARCHAR(32) UNIQUE, total_copies INTEGER NOT NULL CHECK (total_copies > 0), available_copies INTEGER NOT NULL CHECK (available_copies >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS book_issues (id SERIAL PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, book_id INTEGER NOT NULL REFERENCES books(id) ON DELETE CASCADE, issued_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), due_date DATE NOT NULL, returned_at TIMESTAMPTZ, fine_amount NUMERIC(10,2) NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS books_title_idx ON books(title);
CREATE INDEX IF NOT EXISTS books_author_idx ON books(author);
CREATE INDEX IF NOT EXISTS issues_student_idx ON book_issues(student_id);
